Item.method_code:
const {
	commandFactory,
	relatedItemType,
	getState,
	rows
} = options;
const { grid } = getState();
if (!relatedItemType || grid.selectedRows.length !== 1) {
	return { disabled: true };
}

const selectedItemId = grid.selectedRows[0];
const relatedId = rows.get(selectedItemId, 'related_id');
const relatedItem = rows.get(relatedId);
const commandAlias = target['command_alias@keyed_name'];
const openCommand = commandFactory(commandAlias, {
	item: relatedItem,
	itemTypeName: relatedItemType.name,
	itemType: relatedItemType
});

return {
	disabled: !openCommand.canExecute()
};
